import{_ as i,o as l,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Month 2021: Open Discussion","description":"","frontmatter":{"title":"Ceph Month 2021: Open Discussion","date":"2021-06-01T00:00:00.000Z","updated":"2021-06-02T00:00:00.000Z","tags":["Ceph","Distributed Storage","Open Discussion","CephFS","RBD"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Month_2021_-_Open_Discussion.md","filePath":"posts/2021/Ceph_Month_2021_-_Open_Discussion.md","lastUpdated":1780459816000}'),o={name:"posts/2021/Ceph_Month_2021_-_Open_Discussion.md"};function r(s,e,n,p,h,u){return l(),a("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议目的" tabindex="-1">会议目的 <a class="header-anchor" href="#会议目的" aria-label="Permalink to &quot;会议目的&quot;">​</a></h4><p>本次会议旨在通过听取相关演讲和自由形式的讨论，促进与会者就Ceph相关议题进行交流。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>File Store 状态讨论</strong></p><ul><li>讨论了何时停止对File Store的支持，通过Grafana仪表板的数据显示，目前仍有约1500个File Store OSDs在使用，占总数的4%。</li><li>决定是否继续支持File Store的讨论，以及对代码简化和对象存储接口清理的影响。</li></ul></li><li><p><strong>Crimson和File Store的未来</strong></p><ul><li>Crimson将不再支持File Store，这可能导致未来无法继续支持。</li><li>提出了对仍在使用File Store的OSDs发出警告的建议。</li></ul></li><li><p><strong>Dedupe更新</strong></p><ul><li>讨论了Dedupe功能的三个部分：RADOS类、RADOS分层代码的更改以及RADOS网关直接存储数据的支持。</li><li>目前Dedupe功能尚未完全稳定，仍在开发中。</li></ul></li><li><p><strong>Cepheidium对大型集群的支持</strong></p><ul><li>讨论了Cepheidium的扩展限制和计划中的重构，以提高其可扩展性。</li></ul></li><li><p><strong>Ceph部署和管理方式的未来</strong></p><ul><li>讨论了是否继续构建容器和包，以及如何管理通过包安装的Ceph集群。</li><li>强调了尽管有对容器的抵触，但目前没有具体的技术理由反对使用容器。</li></ul></li><li><p><strong>其他议题</strong></p><ul><li>讨论了CephFS和RBD在macOS上的支持情况，以及可能的改进。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>决定继续讨论并最终决定是否停止对File Store的支持。</li><li>计划对仍在使用File Store的OSDs发出警告。</li><li>将继续开发和完善Dedupe功能。</li><li>将继续支持包和容器的构建，但可能减少对多个发行版的支持。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>发送跟进邮件到Ceph用户列表，收集对停止File Store支持的反馈。</li><li>继续开发和测试Dedupe功能，确保其稳定性和可用性。</li><li>继续改进Cepheidium的可扩展性。</li><li>准备一篇博客文章，讨论容器使用的议题，并收集更多反馈。</li></ul><h4 id="下次会议安排" tabindex="-1">下次会议安排 <a class="header-anchor" href="#下次会议安排" aria-label="Permalink to &quot;下次会议安排&quot;">​</a></h4><ul><li>下次会议将于6月10日举行，将包括RGW更新和其他相关议题的讨论。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><p>感谢所有参与者的参与和贡献，期待下次会议再见。</p>',13)])])}const c=i(o,[["render",r]]);export{_ as __pageData,c as default};
